#include <stdio.h>

struct Student {
    char name[30];
    int marks;
};

int main() {
    struct Student students[3] = {
        {"Asha", 88},
        {"Ravi", 74},
        {"Meera", 92}
    };

    for (int i = 0; i < 3; i++) {
        printf("%s scored %d marks\n", students[i].name, students[i].marks);
    }

    return 0;
}
